type Config_LoRaConfig_ModemPreset int32

const (
	// Long Range - Fast
	Config_LoRaConfig_LONG_FAST Config_LoRaConfig_ModemPreset = 0
	// Long Range - Slow
	// Deprecated in 2.7: Unpopular slow preset.
	//
	// Deprecated: Marked as deprecated in meshtastic/config.proto.
	Config_LoRaConfig_LONG_SLOW Config_LoRaConfig_ModemPreset = 1
	// Very Long Range - Slow
	// Deprecated in 2.5: Works only with txco and is unusably slow
	//
	// Deprecated: Marked as deprecated in meshtastic/config.proto.
	Config_LoRaConfig_VERY_LONG_SLOW Config_LoRaConfig_ModemPreset = 2
	// Medium Range - Slow
	Config_LoRaConfig_MEDIUM_SLOW Config_LoRaConfig_ModemPreset = 3
	// Medium Range - Fast
	Config_LoRaConfig_MEDIUM_FAST Config_LoRaConfig_ModemPreset = 4
	// Short Range - Slow
	Config_LoRaConfig_SHORT_SLOW Config_LoRaConfig_ModemPreset = 5
	// Short Range - Fast
	Config_LoRaConfig_SHORT_FAST Config_LoRaConfig_ModemPreset = 6
	// Long Range - Moderately Fast
	Config_LoRaConfig_LONG_MODERATE Config_LoRaConfig_ModemPreset = 7
	// Short Range - Turbo
	// This is the fastest preset and the only one with 500kHz bandwidth.
	// It is not legal to use in all regions due to this wider bandwidth.
	Config_LoRaConfig_SHORT_TURBO Config_LoRaConfig_ModemPreset = 8
	// Long Range - Turbo
	// This preset performs similarly to LongFast, but with 500Khz bandwidth.
	Config_LoRaConfig_LONG_TURBO Config_LoRaConfig_ModemPreset = 9
	// Lite Fast
	// Medium range preset optimized for EU 866MHz SRD band with 125kHz bandwidth.
	// Comparable link budget to MEDIUM_FAST but compliant with Band no. 47b of 2006/771/EC.
	Config_LoRaConfig_LITE_FAST Config_LoRaConfig_ModemPreset = 10
	// Lite Slow
	// Medium-to-moderate range preset optimized for EU 866MHz SRD band with 125kHz bandwidth.
	// Comparable link budget to LONG_FAST but compliant with Band no. 47b of 2006/771/EC.
	Config_LoRaConfig_LITE_SLOW Config_LoRaConfig_ModemPreset = 11
	// Narrow Fast
	// Medium-to-moderate range preset optimized for EU 868MHz band with 62.5kHz bandwidth.
	// Comparable link budget to SHORT_SLOW, but with half the data rate.
	// Intended to avoid interference with other devices.
	Config_LoRaConfig_NARROW_FAST Config_LoRaConfig_ModemPreset = 12
	// Narrow Slow
	// Moderate range preset optimized for EU 868MHz band with 62.5kHz bandwidth.
	// Comparable link budget and data rate to LONG_FAST.
	Config_LoRaConfig_NARROW_SLOW Config_LoRaConfig_ModemPreset = 13
	// Tiny Fast
	// Preset optimized for compliance with Amateur Radio restrictions with 20kHz bandwidth.
	// Many regions limit data transmission bandwidth in lower amateur bands (2 Meter).
	// Note: TCXO with tight tolerances (±5 ppm or better) is *absolutely required* at these narrow bandwidths.
	// Only compatible with SX127x and SX126x chipsets.
	// Comparable link budget and data rate to LONG_FAST.
	Config_LoRaConfig_TINY_FAST Config_LoRaConfig_ModemPreset = 14
	// Tiny Slow
	// Preset optimized for compliance with Amateur Radio restrictions with 20kHz bandwidth.
	// Many regions limit data transmission bandwidth in lower amateur bands (2 Meter).
	// Note: TCXO with tight tolerances (±5 ppm or better) is *absolutely required* at these narrow bandwidths.
	// Only compatible with SX127x and SX126x chipsets.
	// Comparable link budget and data rate to LONG_MODERATE.
	Config_LoRaConfig_TINY_SLOW Config_LoRaConfig_ModemPreset = 15
	// Medium Range - Turbo
	// This preset performs similarly to MEDIUM_FAST, but with 500kHz bandwidth.
	// It is not legal to use in all regions due to this wider bandwidth.
	Config_LoRaConfig_MEDIUM_TURBO Config_LoRaConfig_ModemPreset = 16
)

